sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {
        // Populate Model based on Part id, or set
        // skip to true if no Model can be found.

        // User-supplied mapping of vendor part ids to Model-names,
        // filtered down to only entries where both key and value 
        // are populated.
        // The model-name may be a partial name.
        //
        // [{
        //    "key": "CGX-13",
        //    "value": "Cyberpower Gamer Xtreme 1311"
        //  }, ...]
        var models = new BaseDataSourceReader(gs.getCurrentScopeName(), "Models")
            .getData()
            .filter(e => e.key && e.value);

        // The resolver returns an object describing whether that
        // model-name (@value, above) maps to a Model(valid), or to 
        // nothing (invalid), or to multiple models (also invalid).
        var resolver = new ModelResolver("cmdb_model", "name");

        // Loop through the rows, passing each u_part_id to 
        // the resolver. If the resolver returns a good reference 
        // to a Model, populate that reference into the row, otherwise
        // mark the row skipped.
        var gr_is_row = new GlideRecord(source.getTableName());
        gr_is_row.addQuery("sys_import_set", import_set.sys_id);
        gr_is_row.addQuery("u_skip", false);
        gr_is_row.query();
        while (gr_is_row.hasNext()) {
            gr_is_row.next();

            var part_id = gr_is_row.getValue("u_part_id");

            // We already checked, in a previous script, that
            // each part id is listed in the part id/Model map, so we
            // can skip checking that here

            var modelName = models[part_id];
            var response = resolver.resolve(modelName, false);
            if (response.valid) {
                gr_is_row.setValue("u_model_ref", response.refs[0].sys_id);
                gr_is_row.update();
            } else {
                gr_is_row.setValue("u_skip", true);
                gr_is_row.setValue("u_skip_reason", response.message);
                gr_is_row.update();
            }

        }

})(source, map, log, target);
